import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { useSettingsStore } from '@/store/settingsStore';

/**
 * Generated by scripts/generateSounds.ts. Each clip is padded with trailing silence (see MIN_MS
 * there): a clip shorter than Android's audio buffer was stopped before the output started, and
 * some phones then played nothing.
 */
const SOURCES = {
  exit: require('../../assets/sounds/exit.wav'),
  blocked: require('../../assets/sounds/blocked.wav'),
  win: require('../../assets/sounds/win.wav'),
  hint: require('../../assets/sounds/hint.wav'),
  tap: require('../../assets/sounds/tap.wav'),
  coin: require('../../assets/sounds/coin.wav'),
  smash: require('../../assets/sounds/smash.wav'),
  life: require('../../assets/sounds/life.wav'),
} as const;

export type SoundName = keyof typeof SOURCES;

let players: Record<SoundName, AudioPlayer> | null = null;

/** Creates one player per effect, so each is loaded before its first use. Safe to call repeatedly. */
export function preloadSounds(): void {
  if (players) return;
  // Short effects: never take audio focus from the player's music or podcasts.
  setAudioModeAsync({ interruptionMode: 'mixWithOthers', playsInSilentMode: false }).catch(() => {});
  players = Object.fromEntries(
    Object.entries(SOURCES).map(([name, source]) => [name, createAudioPlayer(source)]),
  ) as Record<SoundName, AudioPlayer>;
}

/** Plays an effect from the start at the chosen volume, if the Sound setting is on. Never throws. */
export function playSound(name: SoundName): void {
  const { soundEnabled, volume } = useSettingsStore.getState();
  if (!soundEnabled || volume <= 0) return;
  try {
    preloadSounds();
    const player = players![name];
    if (player.volume !== volume) player.volume = volume;
    // A player that hasn't played yet is already at the start. One that has rewinds first and
    // plays once the rewind lands: seekTo and play reach the native player by different routes,
    // so sent back to back they could arrive swapped.
    if (player.currentTime > 0 || player.playing) {
      player.seekTo(0).then(
        () => player.play(),
        () => player.play(),
      );
    } else {
      player.play();
    }
  } catch {
    // Audio is decoration; a failed effect must never break a tap.
  }
}
